# Define a class for the digital burrow system
class BurrowCheckpoint {
    [string]$Name
    [string]$Token

    BurrowCheckpoint([string]$name, [string]$token) {
        $this.Name = $name
        $this.Token = $token
    }
}

# Define a class for the burrow system
class BurrowSystem {
    [array]$Checkpoints

    BurrowSystem() {
        $this.Checkpoints = @()
    }

    AddCheckpoint([BurrowCheckpoint]$checkpoint) {
        $this.Checkpoints += $checkpoint
    }

    Checkpoint([string]$name, [string]$token) {
        $checkpoint = $this.Checkpoints | Where-Object {$_.Name -eq $name}
        if ($checkpoint -and $checkpoint.Token -eq $token) {
            Write-Host "Passed checkpoint $name"
            return $true
        }
        Write-Host "Access denied to checkpoint $name"
        return $false
    }
}

